<?php
declare(strict_types=1);
require_once __DIR__.'/fixtures/PrintifyApiApprovalFixture.php';
use DigiForge\Connector\Printify\{NativeBusinessEvidence,NativeAuthorityAdapter,ShopBinding,CredentialReference};
use DigiForge\Database\Tables;
final class NativeBusinessEvidenceTest extends WP_UnitTestCase {
 private PrintifyApiApprovalFixture $fixture;private array $rows=[];
 protected function setUp():void{parent::setUp();$this->fixture=new PrintifyApiApprovalFixture();$this->fixture->boot();global $wpdb;foreach([Tables::opportunities(),Tables::product_families(),Tables::products(),Tables::product_versions(),Tables::production_plans(),Tables::pod_mappings(),Tables::pod_business_mappings()]as $table)$this->rows[$table]=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);DigiForge\Core\Settings::protectProduction();}
 protected function tearDown():void{try{global $wpdb;$wpdb->query('ROLLBACK');foreach($this->rows as $table=>$rows){$wpdb->query('DELETE FROM '.$table);foreach($rows as $row)$wpdb->insert($table,$row,array_fill(0,count($row),'%s'));}$this->fixture->restore();}finally{parent::tearDown();}}
 private function scope():ShopBinding{$v=PrintifyApiApprovalFixture::checked((new DigiForge\POD\ScopedProviderConnection())->verified('personalized_pod',$this->fixture->integration,'printify.connection.read'));return new ShopBinding(2,'personalized_pod',$this->fixture->integration,$v['external_shop_reference'],$v['environment'],$v['review_revision'],new CredentialReference($this->fixture->integration),$v['binding_hash'],$v['expires_at']);}
 private function product():array {
  $s=$this->scope();$a=PrintifyApiApprovalFixture::checked(NativeAuthorityAdapter::scope($s,1));$f=new DigiForge\ProductFactory\Repository();$o=PrintifyApiApprovalFixture::checked($f->create('opportunity',['title'=>'Synthetic Shop2 resolver']));$family=PrintifyApiApprovalFixture::checked($f->create('product_family',['opportunity_id'=>$o['id'],'name'=>'Synthetic mug']));$p=PrintifyApiApprovalFixture::checked($f->create('product',['product_family_id'=>$family['id'],'name'=>'Synthetic FL03']));$v=PrintifyApiApprovalFixture::checked($f->create('product_version',['product_id'=>$p['id'],'version_label'=>'genuine-stored-v1']));
  PrintifyApiApprovalFixture::checked($f->transition('product_family',(int)$family['id'],'ACTIVE'));PrintifyApiApprovalFixture::checked($f->transition('product',(int)$p['id'],'READY'));foreach(['REVIEW','APPROVED']as $state)PrintifyApiApprovalFixture::checked($f->transition('product_version',(int)$v['id'],$state));
  $production=new DigiForge\Production\Repository();$plan=PrintifyApiApprovalFixture::checked($production->createPlan(['product_version_id'=>$v['id'],'plan_key'=>'synthetic','version_label'=>'v1','channel'=>'pod','production_type'=>'POD']));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($production->transition('plan',(int)$plan['id'],$state));
  $pod=new DigiForge\POD\Repository();$m=PrintifyApiApprovalFixture::checked($pod->createMapping(['product_version_id'=>$v['id'],'production_plan_id'=>$plan['id'],'provider'=>'printify','environment'=>'test','provider_product_key'=>'synthetic-product','provider_variant_key'=>'synthetic-variant','mapping_version'=>'v1']));$b=new DigiForge\POD\BusinessScopeRepository();$owner=PrintifyApiApprovalFixture::checked($b->createMapping(['product_version_id'=>$v['id'],'provider_mapping_id'=>$m['id'],'business_id'=>$a['scope']['business_id'],'store_id'=>$a['scope']['store_id'],'product_program'=>'PERSONALIZED_POD']));PrintifyApiApprovalFixture::checked($b->approveMapping((int)$owner['id']));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($pod->transition('mapping',(int)$m['id'],$state));return [$s,(int)$m['id'],(int)$v['id'],(int)$owner['id']];
 }
 public function testStoredVersionIdentityAndExactRevalidationStayHeld():void {
  self::assertTrue(class_exists(NativeBusinessEvidence::class),'Canonical business resolver required.');[$s,$id,$v]=$this->product();$deny=static function(){throw new RuntimeException('No provider calls');};add_filter('pre_http_request',$deny,PHP_INT_MAX);
  try{$r=PrintifyApiApprovalFixture::checked(NativeBusinessEvidence::product($s,1,$id));self::assertSame($v,$r['product_version_id']);self::assertFalse($r['external_execution_authorized']);self::assertNull($r['artwork_source_hash']);self::assertSame($r,NativeBusinessEvidence::product($s,1,$id,$r['evidence_hash']));global $wpdb;self::assertSame(1,$wpdb->update(Tables::product_versions(),['notes'=>'changed after review'],['id'=>$v],['%s'],['%d']));self::assertWPError(NativeBusinessEvidence::product($s,1,$id,$r['evidence_hash']));}finally{remove_filter('pre_http_request',$deny,PHP_INT_MAX);}
 }
 public function testReapprovalCannotReusePriorDependencyFingerprint():void {
  [$s,$id,$v]=$this->product();$r=PrintifyApiApprovalFixture::checked(NativeBusinessEvidence::product($s,1,$id));global $wpdb;$old=$wpdb->get_var($wpdb->prepare('SELECT updated_at FROM '.Tables::product_versions().' WHERE id=%d',$v));$f=new DigiForge\ProductFactory\Repository();foreach(['REVIEW','APPROVED']as $state)PrintifyApiApprovalFixture::checked($f->transition('product_version',$v,$state));$wpdb->update(Tables::product_versions(),['updated_at'=>$old],['id'=>$v],['%s'],['%d']);self::assertWPError(NativeBusinessEvidence::product($s,1,$id,$r['evidence_hash']));$new=PrintifyApiApprovalFixture::checked(NativeBusinessEvidence::product($s,1,$id));self::assertGreaterThan($r['product_approval_event_id'],$new['product_approval_event_id']);
 }
 public static function deniedStates():array{return [['version'],['owner'],['mapping'],['foreign_shop'],['revoked'],['missing_storage'],['outer_transaction'],['commit_unknown'],['changed_at_commit'],['ambiguous'],['approval_missing'],['rollback_unknown'],['temporary_shadow'],['overflow'],['revoked_at_commit'],['approval_actor'],['plan_approval_actor'],['temporary_audit']];}
 /** @dataProvider deniedStates */
 public function testInvalidOrUnavailableBusinessEvidenceDenies(string $mode):void {
  self::assertTrue(class_exists(NativeBusinessEvidence::class));[$s,$id,$v,$owner]=$this->product();global $wpdb;
  if($mode==='version')$wpdb->update(Tables::product_versions(),['state'=>'REVIEW'],['id'=>$v],['%s'],['%d']);elseif($mode==='owner')$wpdb->update(Tables::pod_business_mappings(),['store_id'=>2147483647],['id'=>$owner],['%d'],['%d']);elseif($mode==='mapping')$wpdb->update(Tables::pod_mappings(),['state'=>'SUPERSEDED'],['id'=>$id],['%s'],['%d']);elseif($mode==='foreign_shop')$s=new ShopBinding(3,'standard_pod',$s->integrationId,$s->providerShopId,$s->environment,$s->revision,$s->credential,$s->bindingHash,$s->expiresAt);elseif($mode==='revoked')WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());elseif($mode==='outer_transaction')$wpdb->query('START TRANSACTION');elseif($mode==='ambiguous'){$copy=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_business_mappings().' WHERE id=%d',$owner),ARRAY_A);unset($copy['id']);$copy['product_version_id']=$v+214748;$copy['idempotency_key']=null;self::assertSame(1,$wpdb->insert(Tables::pod_business_mappings(),$copy,array_fill(0,count($copy),'%s')));}
  if(in_array($mode,['approval_actor','plan_approval_actor'],true)){$map=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::pod_mappings().' WHERE id=%d',$id),ARRAY_A);$type=$mode==='approval_actor'?'mapping':'plan';$event=$mode==='approval_actor'?'pod_state_changed':'production_state_changed';$target=$mode==='approval_actor'?$id:(int)$map['production_plan_id'];self::assertSame(3,$wpdb->update(Tables::audit_log(),['actor_id'=>$this->fixture->reviewer],['object_type'=>$type,'event_type'=>$event,'object_id'=>(string)$target],['%d'],['%s','%s','%s']));}
  if($mode==='temporary_audit'){$table=Tables::audit_log();$rows=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);$ddl=$wpdb->get_row('SHOW CREATE TABLE '.$table,ARRAY_N);self::assertNotFalse($wpdb->query(preg_replace('/^CREATE TABLE/','CREATE TEMPORARY TABLE',$ddl[1])));foreach($rows as $row)self::assertSame(1,$wpdb->insert($table,$row,array_fill(0,count($row),'%s')));}
  if($mode==='overflow')self::assertSame(1,$wpdb->update(Tables::pod_mappings(),['product_version_id'=>'18446744073709551615'],['id'=>$id],['%s'],['%d']));if($mode==='approval_missing')$wpdb->delete(Tables::audit_log(),['event_type'=>'product_version_state_changed','object_id'=>(string)$v],['%s','%s']);if($mode==='temporary_shadow'){$ddl=$wpdb->get_row('SHOW CREATE TABLE '.Tables::pod_mappings(),ARRAY_N);self::assertNotFalse($wpdb->query(preg_replace('/^CREATE TABLE/','CREATE TEMPORARY TABLE',$ddl[1])));$shadow=$wpdb->get_row('SHOW CREATE TABLE '.Tables::pod_mappings(),ARRAY_N);self::assertStringContainsString('CREATE TEMPORARY TABLE',$shadow[1]);}$filter=static fn(string $q):string=>str_contains($q,'FROM '.Tables::pod_mappings().' WHERE')?'SELECT * FROM missing_native_business_evidence':$q;if(in_array($mode,['missing_storage','rollback_unknown'],true))add_filter('query',$filter);$changed=false;$boundary=static function(string $q)use($mode,&$changed,$wpdb,$v):string{if($mode==='rollback_unknown'&&$q==='ROLLBACK')return 'SELECT * FROM missing_rollback_confirmation';if($q==='COMMIT'&&!$changed){$changed=true;if($mode==='commit_unknown')return 'SELECT * FROM missing_business_commit_confirmation';if($mode==='revoked_at_commit'){$wpdb->query('COMMIT');WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());}if($mode==='changed_at_commit'){$wpdb->query('COMMIT');$wpdb->update(Tables::product_versions(),['notes'=>'concurrent change'],['id'=>$v],['%s'],['%d']);}}return $q;};if(in_array($mode,['commit_unknown','changed_at_commit','rollback_unknown','revoked_at_commit'],true))add_filter('query',$boundary);
  try{$denied=NativeBusinessEvidence::product($s,1,$id);self::assertWPError($denied);if($mode==='rollback_unknown')self::assertSame('printify_native_business_cleanup_unknown',$denied->get_error_code());if($mode==='outer_transaction')self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertTrue(DigiForge\Core\Settings::safety_locked());}finally{if(in_array($mode,['missing_storage','rollback_unknown'],true))remove_filter('query',$filter);if(in_array($mode,['commit_unknown','changed_at_commit','rollback_unknown','revoked_at_commit'],true)){remove_filter('query',$boundary);if($mode!=='rollback_unknown')self::assertTrue($changed);}if($mode==='temporary_shadow')$wpdb->query('DROP TEMPORARY TABLE '.Tables::pod_mappings());if($mode==='temporary_audit')$wpdb->query('DROP TEMPORARY TABLE '.Tables::audit_log());}
 }
}
